# name: balanced_choice_at_equal_switches
# description: Among pairs whose two sequences have the same number of switches but different |#H-#T| imbalance, the rate of choosing the more balanced sequence; observed above null means the model under-weights heads/tails balance (it only has a linear heads-share term, no symmetric balance term).
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    def sw(s):
        u = pd.Series(s.unique())
        m = {x: sum(1 for p, q in zip(x, x[1:]) if p != q) for x in u}
        return s.map(m)
    ia = (2 * a.str.count("H") - a.str.len()).abs()
    ib = (2 * b.str.count("H") - b.str.len()).abs()
    mask = (sw(a) == sw(b)) & (ia != ib)
    if mask.sum() == 0:
        return 0.5
    left_more_bal = (ia < ib)[mask]
    c = df["chose_left"][mask]
    return float(np.where(left_more_bal, c, 1 - c).mean())

# name: shorter_longest_run_at_equal_switches
# description: Among pairs with equal switch counts but different longest-run lengths, the rate of choosing the sequence with the shorter longest run; observed above null means the model under-penalizes long streaks beyond what the switching rate implies.
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    def feat(s, f):
        return s.map({x: f(x) for x in s.unique()})
    def sw(x):
        return sum(1 for p, q in zip(x, x[1:]) if p != q)
    def lr(x):
        best = cur = 1
        for p, q in zip(x, x[1:]):
            cur = cur + 1 if p == q else 1
            best = max(best, cur)
        return best
    la, lb = feat(a, lr), feat(b, lr)
    mask = (feat(a, sw) == feat(b, sw)) & (la != lb)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"][mask]
    return float(np.where((la < lb)[mask], c, 1 - c).mean())

# name: symmetric_pattern_avoidance
# description: Among pairs where exactly one sequence is a palindrome or a complement-mirror (e.g. HHTT-like reversals) but neither is periodic, the rate of choosing the non-symmetric sequence; observed above null means people penalize visible symmetry that the model (only periodicity and switching) does not capture.
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    tr = str.maketrans("HT", "TH")
    def sym(x):
        r = x[::-1]
        return float(x == r or x == r.translate(tr))
    def per(x):
        n = len(x)
        return float(any(all(x[i] == x[i + p] for i in range(n - p)) for p in range(1, n // 2 + 1)))
    def f(s, g):
        return s.map({x: g(x) for x in s.unique()})
    ya, yb = f(a, sym), f(b, sym)
    mask = (ya != yb) & (f(a, per) == 0) & (f(b, per) == 0)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"][mask]
    return float(np.where((ya < yb)[mask], c, 1 - c).mean())

# name: participant_side_bias_variance
# description: Variance across participants of their proportion of Left choices; observed above null means individual side/response biases (or lapsing) that the model lacks and so under-produces.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().var(ddof=0))

# name: left_choice_rate
# description: Overall proportion of Left choices; observed away from null means a screen-side bias that the model (no side term) fails to reproduce.
def test_statistic(df):
    return float(df["chose_left"].mean())

# name: heads_choice_at_equal_switches
# description: Among pairs with equal switch counts and equal |#H-#T| imbalance but different head counts (mirror-type pairs), the rate of choosing the more-heads sequence; observed differing from null means the model's linear heads-share weight misstates the pure label asymmetry (above: model under-produces heads preference; below: over-produces).
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    def sw(s):
        return s.map({x: sum(1 for p, q in zip(x, x[1:]) if p != q) for x in s.unique()})
    ha, hb = a.str.count("H"), b.str.count("H")
    ia = (2 * ha - a.str.len()).abs()
    ib = (2 * hb - b.str.len()).abs()
    mask = (sw(a) == sw(b)) & (ia == ib) & (ha != hb)
    if mask.sum() == 0:
        mask = (sw(a) == sw(b)) & (ha != hb)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"][mask]
    return float(np.where((ha > hb)[mask], c, 1 - c).mean())

# name: start_symbol_heads_preference
# description: Among pairs where one sequence starts with H and the other with T, the rate of choosing the H-starting sequence; observed above null means the first flip's label matters beyond overall head count (model under-produces this), below means the opposite.
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    sa, sb = a.str[0], b.str[0]
    mask = sa != sb
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"][mask]
    return float(np.where((sa == "H")[mask], c, 1 - c).mean())
